const TEAM_ALIASES = { WAS: "WSH", LA: "LAR", OAK: "LV", SD: "LAC", STL: "LAR" };

function normaliseName(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\b(jr|sr|ii|iii|iv)\b\.?/g, "")
    .replace(/[^a-z0-9]/g, "");
}

function normaliseTeam(value) {
  const code = String(value || "").trim().toUpperCase();
  return TEAM_ALIASES[code] || code;
}

const RATINGS_BY_NAME = new Map();
for (const player of MADDEN_PLAYERS) {
  const key = normaliseName(player.n);
  const existing = RATINGS_BY_NAME.get(key) || [];
  existing.push(player);
  RATINGS_BY_NAME.set(key, existing);
}

export function getPlayerRating(playerOrName, teamCode) {
  const name = typeof playerOrName === "string"
    ? playerOrName
    : playerOrName?.fullName || playerOrName?.full_name || playerOrName?.name;
  const matches = RATINGS_BY_NAME.get(normaliseName(name)) || [];
  if (!matches.length) return null;

  const expectedTeam = normaliseTeam(
    teamCode || playerOrName?.team || playerOrName?.teamAbbreviation
  );
  const match = matches.find((candidate) => normaliseTeam(candidate.t) === expectedTeam) || matches[0];

  return {
    name: match.n,
    team: match.t,
    position: match.p,
    overall: match.o,
  };
}

export function resolveFullPlayerName(playerOrName, teamCode) {
  const rawName = typeof playerOrName === "string"
    ? playerOrName
    : playerOrName?.fullName || playerOrName?.full_name || playerOrName?.displayName ||
      playerOrName?.display_name || playerOrName?.name || playerOrName?.playerName ||
      playerOrName?.player_name || "";
  const text = String(rawName || "").trim();
  if (!text) return "";

  const direct = getPlayerRating(playerOrName, teamCode);
  if (direct?.name) return direct.name;

  const compact = text
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\b(jr|sr|ii|iii|iv)\b\.?/gi, "")
    .replace(/[^A-Za-z0-9]/g, "")
    .toLowerCase();
  const abbreviated = compact.match(/^([a-z])([a-z][a-z0-9'-]+)$/i);
  if (!abbreviated) return text;

  const initial = abbreviated[1];
  const surname = abbreviated[2];
  const expectedTeam = normaliseTeam(
    teamCode || playerOrName?.team || playerOrName?.teamAbbreviation
  );
  const matches = MADDEN_PLAYERS.filter((candidate) => {
    const parts = String(candidate.n || "").trim().split(/\s+/);
    if (parts.length < 2) return false;
    const first = normaliseName(parts[0]);
    const last = normaliseName(parts.slice(1).join(" "));
    return first.startsWith(initial) && last === surname;
  });
  const teamMatch = matches.find((candidate) => normaliseTeam(candidate.t) === expectedTeam);
  const match = teamMatch || (matches.length === 1 ? matches[0] : null);
  return match?.n || text;
}

export function getTeamPlayerRatings(teamCode) {
  const expectedTeam = normaliseTeam(teamCode);
  return MADDEN_PLAYERS
    .filter((player) => normaliseTeam(player.t) === expectedTeam)
    .map((player) => ({ name: player.n, team: player.t, position: player.p, overall: player.o }));
}

export function getPlayerRatingsHealth() {
  const teams = new Set(MADDEN_PLAYERS.map((player) => player.t).filter((team) => team !== "FA"));
  return { loaded: MADDEN_PLAYERS.length > 0, players: MADDEN_PLAYERS.length, teams: teams.size };
}
